self.addEventListener('install', ev => {
  ev.waitUntil(caches.open(CORE_CACHE).then(c => c.addAll(CORE.map(u => new Request(u, {cache: 'reload'})))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', ev => {
  ev.waitUntil((async () => {
    const keep = new Set([CORE_CACHE, IMG_CACHE]);
    for (const k of await caches.keys()) if (!keep.has(k)) await caches.delete(k);
    const ic = await caches.open(IMG_CACHE), want = new Set(IMAGES.map(u => new URL(u, self.registration.scope).href));
    for (const req of await ic.keys()) if (!want.has(req.url)) await ic.delete(req);
    await self.clients.claim();
  })());
});

let caching = null;
async function cacheImages() {
  const ic = await caches.open(IMG_CACHE); let done = 0, failed = 0; const total = IMAGES.length;
  const post = async (final) => { for (const cl of await self.clients.matchAll()) cl.postMessage({type: 'img-progress', done, total, failed, final}); };
  for (let i = 0; i < IMAGES.length; i += 6) {
    await Promise.all(IMAGES.slice(i, i + 6).map(async u => {
      try { if (!(await ic.match(u))) { const r = await fetch(u, {cache: 'reload'}); if (!r.ok) throw new Error(r.status); await ic.put(u, r); } done++; }
      catch (e) { failed++; }
    }));
    await post(false);
  }
  await post(true); caching = null;
}
self.addEventListener('message', ev => {
  if ((ev.data || {}).type === 'cache-images') { if (!caching) caching = cacheImages(); ev.waitUntil(caching); }
});

self.addEventListener('fetch', ev => {
  const req = ev.request; if (req.method !== 'GET') return;
  const url = new URL(req.url); if (url.origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    ev.respondWith((async () => (await caches.match('index.html', {ignoreSearch: true})) || fetch(req))());
    return;
  }
  ev.respondWith((async () => {
    const hit = await caches.match(req, {ignoreSearch: true}); if (hit) return hit;
    const r = await fetch(req);
    if (r.ok && /\/images\//.test(url.pathname)) { const c = await caches.open(IMG_CACHE); c.put(req, r.clone()); }
    return r;
  })());
});
